 29	export function compileQuest(id) {
 30	  const def = getQuestDef(id);
 31	  if (!def) throw new Error(`compileQuest: unknown quest '${id}'`);
 32	  const key = cacheKey(def.id, def.version || 1);
 33	  if (COMPILED_QUESTS.has(key)) return COMPILED_QUESTS.get(key);
 34	
 35	  const nodes = Object.freeze({ ...(def.nodes || {}) });
 36	  const edgesByEvent = new Map();
 37	  const eventNames = new Set();
 38	
 39	  for (const [nodeId, nodeDef] of Object.entries(nodes)) {
 40	    const on = (nodeDef && typeof nodeDef === "object" && nodeDef.on && typeof nodeDef.on === "object")
 41	      ? nodeDef.on
 42	      : {};
 43	    for (const [eventName, rawEdges] of Object.entries(on)) {
 44	      if (!Array.isArray(rawEdges) || rawEdges.length <= 0) continue;
 45	      eventNames.add(eventName);
 46	      const list = edgesByEvent.get(eventName) || [];
 47	      for (const edge of rawEdges) {
 48	        list.push(Object.freeze({
 49	          from: nodeId,
 50	          to: String(edge?.to || ""),
 51	          guard: typeof edge?.guard === "function" ? edge.guard : null,
 52	          actions: Array.isArray(edge?.actions) ? edge.actions.filter((fn) => typeof fn === "function") : [],
 53	        }));
 54	      }
 55	      edgesByEvent.set(eventName, Object.freeze(list));
 56	    }
 57	  }
 58	
 59	  const compiled = Object.freeze({
 60	    id: String(def.id),
 61	    version: Number(def.version || 1),
 62	    title: String(def.title || def.id),
 63	    vars: Object.freeze({ ...(def.vars || {}) }),
 64	    nodes,
 65	    edgesByEvent,
 66	    eventNames: Object.freeze(Array.from(eventNames)),
 67	    bindings: Object.freeze({ ...(def.bindings || {}) }),
 68	  });
 69	  COMPILED_QUESTS.set(key, compiled);
 70	  return compiled;
 71	}
