 73	export function listQuestEventNames() {
 74	  const out = new Set();
 75	  for (const def of QUEST_DEFS.values()) {
 76	    const compiled = compileQuest(def.id);
 77	    for (const eventName of compiled.eventNames) out.add(eventName);
 78	  }
 79	  return Array.from(out.values());
 80	}
